                icons.append((r,c))
    # The blank areas between the icons are filled with 1s as a frame
    # around their 3x3 blocks, on the adjacent row/column tracks.
    for r,c in icons:
        # For each other icon, fill the row and column band toward it,
        # leaving the original icon cells untouched.
        for rr in range(r-1, r+2):
            if not 0 <= rr < h: continue
            for cc in range(w):
                if grid[rr][cc] == 0 and any(ic != (r,c) and ic[0] == rr for ic in icons):
                    out[rr][cc] = 1
        for cc in range(c-1, c+2):
            if not 0 <= cc < w: continue
            for rr in range(h):
                if grid[rr][cc] == 0 and any(ic != (r,c) and ic[1] == cc for ic in icons):
                    out[rr][cc] = 1
    # Precisely, extend each icon's horizontal row and vertical column in 1s,
    # stopping at the next icon's 3x3 boundary and ignoring 2 separators.
    for r,c in icons:
        for dc in (-1,1):
            cc=c+dc
            while 0<=cc<w and grid[r][cc]!=2 and grid[r][cc]!=3:
                if grid[r][cc]==0: out[r][cc]=1
                cc+=dc
        for dr in (-1,1):
            rr=r+dr
            while 0<=rr<h and grid[rr][c]!=2 and grid[rr][c]!=3:
                if grid[rr][c]==0: out[rr][c]=1
                rr+=dr
        # Adjacent-row/column rails get ones across the available neighboring area.
        for rr in (r-1,r+1):
            if 0<=rr<h:
                # fill horizontal span over to the next icon's column region
                for cc in range(w):
                    if grid[rr][cc]==2: out[rr][cc]=1
        for cc in (c-1,c+1):
            if 0<=cc<w:
                for rr in range(h):
                    if grid[rr][cc]==2: out[rr][cc]=1
    return out
''')
